// @FIGURE_CODE_BEGIN
/* ELEMENT SPEC
   camera center        -> SphereGeometry(0.18)  black, draggable
   camera image plane   -> Line (closed)  black outline, 3.2 x 4.0, near-vertical
   image axes x,y       -> cylinder+cone arrows  #00E000 (len 1.0 / 1.2)
   planar surface       -> quad Mesh #C8C8C8 + closed black Line + dashed black diagonal
   world axes X,Y,Z     -> cylinder+cone arrows #FF0000 (len 1.2) + black L right-angle mark
   image of surface     -> quad Mesh #C8C8C8 + closed black Line + dashed black diagonal
                           (recomputed by ray/plane intersection every update)
   projection rays (4)  -> Line + LineDashedMaterial black, C -> surface corner
   helper lines (2)     -> Line + LineDashedMaterial #CCCCCC, C -> near image-plane corners
   cyan points (2)      -> SphereGeometry(0.11) #00E5FF
   cyan ray             -> Line + LineDashedMaterial #00E5FF, C -> (X,Y,0)
   grid + its image     -> thin Lines (#333) on the plane and projected into the image plane
   flattened mode       -> two coplanar panels: square grid (left) and H-warped grid (right)
*/

/* ── constants ─────────────────────────────────────────────────────────── */
const IMG_Q  = new THREE.Vector3(-1.2, 0.0, 0.4);
const IMG_R  = new THREE.Vector3(-0.2, 0, -0.98).normalize();
const IMG_UP = new THREE.Vector3(0, 1, 0);
const IMG_N  = new THREE.Vector3().crossVectors(IMG_R, IMG_UP).normalize();
const IMG_HW = 1.6, IMG_HH = 2.0;
const PL_O   = new THREE.Vector3(3.2, -1.5, 0.3);
const PL_HU  = 2.5, PL_HV = 1.7;
const C_GRAY = 0xC8C8C8, C_CYAN = 0x00E5FF, C_GREEN = 0x00E000, C_RED = 0xFF0000;
const NX = 7, NY = 5;

const VIEW3D   = { projection:'perspective', azimuthDeg:35, elevationDeg:22, rollDeg:0, heightFraction:0.65 };
const VIEWFLAT = { projection:'perspective', azimuthDeg:90, elevationDeg:0,  rollDeg:0, heightFraction:0.78 };

const S = {
  camC: new THREE.Vector3(-4.2, 1.6, 1.0),
  planeTilt: 25, pointX: 0.9, pointY: 0.6,
  flat: false, showGrid: true, showH: true
};

/* ── small builders ────────────────────────────────────────────────────── */
function makeLine(color, o = {}) {
  const dashed = !!o.dashed;
  const mat = dashed
    ? new THREE.LineDashedMaterial({ color, dashSize:o.dash ?? 0.20, gapSize:o.gap ?? 0.15,
        transparent:(o.opacity ?? 1) < 1, opacity:o.opacity ?? 1 })
    : new THREE.LineBasicMaterial({ color, transparent:(o.opacity ?? 1) < 1, opacity:o.opacity ?? 1 });
  const l = new THREE.Line(new THREE.BufferGeometry(), mat);
  l.userData.dashed = dashed;
  return l;
}
function setPts(line, pts) {
  line.geometry.dispose();
  line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  if (line.userData.dashed) line.computeLineDistances();
}
function makeQuad(color, opacity) {
  const m = new THREE.MeshBasicMaterial({ color, side:THREE.DoubleSide, transparent:true,
    opacity, polygonOffset:true, polygonOffsetFactor:2, polygonOffsetUnits:2 });
  return new THREE.Mesh(new THREE.BufferGeometry(), m);
}
function setQuad(mesh, c) {
  const a = new Float32Array([
    c[0].x,c[0].y,c[0].z, c[1].x,c[1].y,c[1].z, c[2].x,c[2].y,c[2].z,
    c[0].x,c[0].y,c[0].z, c[2].x,c[2].y,c[2].z, c[3].x,c[3].y,c[3].z ]);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(a, 3));
  g.computeBoundingSphere();
  mesh.geometry.dispose();
  mesh.geometry = g;
}
function makeArrow(color, shaftR, headR, headL) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, 1, 10), mat);
  const head  = new THREE.Mesh(new THREE.ConeGeometry(headR, headL, 16), mat);
  g.add(shaft, head);
  const YUP = new THREE.Vector3(0, 1, 0);
  g.userData.set = (origin, dir, len) => {
    const dn = dir.clone().normalize();
    const sl = Math.max(0.01, len - headL);
    shaft.scale.set(1, sl, 1);
    shaft.position.copy(origin).addScaledVector(dn, sl / 2);
    head.position.copy(origin).addScaledVector(dn, sl + headL / 2);
    const q = new THREE.Quaternion().setFromUnitVectors(YUP, dn);
    shaft.quaternion.copy(q); head.quaternion.copy(q);
  };
  return g;
}

/* ── geometry math ─────────────────────────────────────────────────────── */
function planeBasis(deg) {
  const a = THREE.MathUtils.degToRad(deg);
  return { u:new THREE.Vector3(1,0,0),
           v:new THREE.Vector3(0, Math.sin(a), -Math.cos(a)),
           n:new THREE.Vector3(0, Math.cos(a),  Math.sin(a)) };
}
function worldPt(B, X, Y) {
  return PL_O.clone().addScaledVector(B.u, X).addScaledVector(B.v, Y);
}
function projImg(W) {
  const dir = W.clone().sub(S.camC);
  const den = IMG_N.dot(dir);
  if (Math.abs(den) < 1e-6) return null;
  const t = IMG_N.dot(IMG_Q.clone().sub(S.camC)) / den;
  if (!isFinite(t)) return null;
  return S.camC.clone().addScaledVector(dir, t);
}
function computeH() {
  const B = planeBasis(S.planeTilt);
  const A = PL_O.clone().sub(S.camC);
  const e = S.camC.clone().sub(IMG_Q);
  const D = IMG_Q.clone().sub(S.camC).dot(IMG_N);
  const a0 = IMG_N.dot(A), a1 = IMG_N.dot(B.u), a2 = IMG_N.dot(B.v);
  const er = e.dot(IMG_R), et = e.dot(IMG_UP);
  const Ar = A.dot(IMG_R), At = A.dot(IMG_UP);
  const ur = B.u.dot(IMG_R), ut = B.u.dot(IMG_UP);
  const vr = B.v.dot(IMG_R), vt = B.v.dot(IMG_UP);
  return [
    [er*a1 + D*ur, er*a2 + D*vr, er*a0 + D*Ar],
    [et*a1 + D*ut, et*a2 + D*vt, et*a0 + D*At],
    [a1, a2, a0]
  ];
}
function applyH(H, X, Y) {
  const w = H[2][0]*X + H[2][1]*Y + H[2][2];
  return [ (H[0][0]*X + H[0][1]*Y + H[0][2]) / w,
           (H[1][0]*X + H[1][1]*Y + H[1][2]) / w ];
}

/* ── 3D group ──────────────────────────────────────────────────────────── */
const g3d = new THREE.Group();
scene.add(g3d);

const camSphere = new THREE.Mesh(new THREE.SphereGeometry(0.18, 24, 18),
                                 new THREE.MeshBasicMaterial({ color:0x000000 }));
g3d.add(camSphere);

const imgPlaneOutline = makeLine(0x000000);
g3d.add(imgPlaneOutline);

const surfMesh = makeQuad(C_GRAY, 0.95);
const surfOutline = makeLine(0x000000);
const surfDiag = makeLine(0x000000, { dashed:true, dash:0.24, gap:0.18 });
g3d.add(surfMesh, surfOutline, surfDiag);

const imgMesh = makeQuad(C_GRAY, 0.95);
const imgOutline = makeLine(0x000000);
const imgDiag = makeLine(0x000000, { dashed:true, dash:0.14, gap:0.11 });
g3d.add(imgMesh, imgOutline, imgDiag);

const rays = [];
for (let i = 0; i < 4; i++) { const r = makeLine(0x000000, { dashed:true, dash:0.26, gap:0.20 }); rays.push(r); g3d.add(r); }
const helpers = [];
for (let i = 0; i < 2; i++) { const h = makeLine(0xCCCCCC, { dashed:true, dash:0.16, gap:0.13 }); helpers.push(h); g3d.add(h); }

const axX = makeArrow(C_GREEN, 0.035, 0.115, 0.30);
const axY = makeArrow(C_GREEN, 0.035, 0.115, 0.30);
g3d.add(axX, axY);
const wX = makeArrow(C_RED, 0.038, 0.125, 0.32);
const wY = makeArrow(C_RED, 0.038, 0.125, 0.32);
const wZ = makeArrow(C_RED, 0.038, 0.125, 0.32);
const lMark = makeLine(0x000000);
g3d.add(wX, wY, wZ, lMark);

const ptWorld = new THREE.Mesh(new THREE.SphereGeometry(0.12, 20, 14), new THREE.MeshBasicMaterial({ color:C_CYAN }));
const ptImage = new THREE.Mesh(new THREE.SphereGeometry(0.11, 20, 14), new THREE.MeshBasicMaterial({ color:C_CYAN }));
const cyanRay = makeLine(C_CYAN, { dashed:true, dash:0.26, gap:0.18 });
g3d.add(ptWorld, ptImage, cyanRay);

const gridG = new THREE.Group(); g3d.add(gridG);
const planeGrid = [], imgGrid = [];
for (let i = 0; i < NX + NY; i++) {
  const a = makeLine(0x333333, { opacity:0.55 });
  const b = makeLine(0x333333, { opacity:0.6 });
  planeGrid.push(a); imgGrid.push(b); gridG.add(a, b);
}

/* static image-plane outline */
const IPC = [
  IMG_Q.clone().addScaledVector(IMG_R, -IMG_HW).addScaledVector(IMG_UP,  IMG_HH),
  IMG_Q.clone().addScaledVector(IMG_R,  IMG_HW).addScaledVector(IMG_UP,  IMG_HH),
  IMG_Q.clone().addScaledVector(IMG_R,  IMG_HW).addScaledVector(IMG_UP, -IMG_HH),
  IMG_Q.clone().addScaledVector(IMG_R, -IMG_HW).addScaledVector(IMG_UP, -IMG_HH)
];
setPts(imgPlaneOutline, [...IPC, IPC[0]]);

/* ── flattened group ───────────────────────────────────────────────────── */
const gflat = new THREE.Group();
const FL_LC = new THREE.Vector3(-2.3, 0.15, 0);
const FL_RC = new THREE.Vector3( 2.3, 0.15, 0);
const FL_S  = 1.35 / PL_HU;

const fSrcOut = makeLine(0x000000), fImgOut = makeLine(0x000000);
const fSrcMesh = makeQuad(C_GRAY, 0.9), fImgMesh = makeQuad(C_GRAY, 0.9);
gflat.add(fSrcMesh, fImgMesh, fSrcOut, fImgOut);
const fSrcGrid = [], fImgGrid = [];
for (let i = 0; i < NX + NY; i++) {
  const a = makeLine(0x333333, { opacity:0.6 }); const b = makeLine(0x333333, { opacity:0.6 });
  fSrcGrid.push(a); fImgGrid.push(b); gflat.add(a, b);
}
const fPtS = new THREE.Mesh(new THREE.SphereGeometry(0.09, 18, 12), new THREE.MeshBasicMaterial({ color:C_CYAN }));
const fPtI = new THREE.Mesh(new THREE.SphereGeometry(0.09, 18, 12), new THREE.MeshBasicMaterial({ color:C_CYAN }));
const fLink = makeLine(C_CYAN, { dashed:true, dash:0.14, gap:0.10 });
gflat.add(fPtS, fPtI, fLink);
const fAxX = makeArrow(C_RED, 0.028, 0.09, 0.22), fAxY = makeArrow(C_RED, 0.028, 0.09, 0.22);
gflat.add(fAxX, fAxY);
const fHarrow = makeArrow(0x000000, 0.03, 0.10, 0.26);
gflat.add(fHarrow);
fHarrow.userData.set(new THREE.Vector3(-0.72, 0.15, 0), new THREE.Vector3(1, 0, 0), 1.44);

/* ── update ────────────────────────────────────────────────────────────── */
function update3D() {
  const B = planeBasis(S.planeTilt);
  const C = S.camC;
  camSphere.position.copy(C);

  const cs = [ worldPt(B,-PL_HU,-PL_HV), worldPt(B, PL_HU,-PL_HV),
               worldPt(B, PL_HU, PL_HV), worldPt(B,-PL_HU, PL_HV) ];
  setQuad(surfMesh, cs);
  setPts(surfOutline, [...cs, cs[0]]);
  setPts(surfDiag, [cs[0], cs[2]]);

  const ic = cs.map(projImg);
  if (ic.every(p => p)) {
    setQuad(imgMesh, ic);
    setPts(imgOutline, [...ic, ic[0]]);
    setPts(imgDiag, [ic[0], ic[2]]);
  }
  for (let i = 0; i < 4; i++) setPts(rays[i], [C, cs[i]]);
  setPts(helpers[0], [C, IPC[0]]);
  setPts(helpers[1], [C, IPC[3]]);

  /* green image axes at lower-left corner of the camera plane */
  const go = IPC[3].clone();
  axY.userData.set(go, IMG_UP, 1.2);
  axX.userData.set(go, IMG_R, 1.0);

  /* red world frame */
  const wo = worldPt(B, -1.1, -0.5);
  wX.userData.set(wo, B.u, 1.2);
  wY.userData.set(wo, B.v, 1.2);
