function updateFlat() {
  const H = computeH();
  const corner = [[-PL_HU,-PL_HV],[PL_HU,-PL_HV],[PL_HU,PL_HV],[-PL_HU,PL_HV]];
  const ims = corner.map(c => applyH(H, c[0], c[1]));
  let mnx = 1e9, mxx = -1e9, mny = 1e9, mxy = -1e9;
  for (const p of ims) { mnx = Math.min(mnx,p[0]); mxx = Math.max(mxx,p[0]); mny = Math.min(mny,p[1]); mxy = Math.max(mxy,p[1]); }
  const cx = (mnx+mxx)/2, cy = (mny+mxy)/2;
  const sc = 1.35 / Math.max((mxx-mnx)/2, (mxy-mny)/2, 1e-3);
  const sp = (X,Y) => new THREE.Vector3(FL_LC.x + X*FL_S, FL_LC.y + Y*FL_S, 0);
  const ip = (X,Y) => { const q = applyH(H,X,Y); return new THREE.Vector3(FL_RC.x + (q[0]-cx)*sc, FL_RC.y + (q[1]-cy)*sc, 0); };

  const sq = corner.map(c => sp(c[0], c[1]));
  const iq = corner.map(c => ip(c[0], c[1]));
  setQuad(fSrcMesh, sq); setPts(fSrcOut, [...sq, sq[0]]);
  setQuad(fImgMesh, iq); setPts(fImgOut, [...iq, iq[0]]);

  let k = 0;
  for (let i = 0; i < NX; i++) {
    const X = -PL_HU + 2*PL_HU*i/(NX-1);
    setPts(fSrcGrid[k], [sp(X,-PL_HV), sp(X,PL_HV)]);
    setPts(fImgGrid[k], [ip(X,-PL_HV), ip(X,PL_HV)]);
    k++;
  }
  for (let j = 0; j < NY; j++) {
    const Y = -PL_HV + 2*PL_HV*j/(NY-1);
    setPts(fSrcGrid[k], [sp(-PL_HU,Y), sp(PL_HU,Y)]);
    setPts(fImgGrid[k], [ip(-PL_HU,Y), ip(PL_HU,Y)]);
    k++;
  }
  const a = sp(S.pointX, S.pointY), b = ip(S.pointX, S.pointY);
  fPtS.position.copy(a); fPtI.position.copy(b);
  setPts(fLink, [a, b]);
  fAxX.userData.set(sp(0,0), new THREE.Vector3(1,0,0), 0.75);
  fAxY.userData.set(sp(0,0), new THREE.Vector3(0,1,0), 0.75);

  if (L.fSrc) {
    L.fSrc.pos.set(FL_LC.x, FL_LC.y - 1.35, 0);
    L.fImg.pos.set(FL_RC.x, FL_RC.y - 1.55, 0);
    L.fH.pos.set(0, FL_LC.y + 0.42, 0);
    L.fEq.pos.set(0, FL_LC.y - 0.42, 0);
    L.fPS.pos.copy(a);
    L.fPI.pos.copy(b);
  }
}

