setCameraView(VIEW3D);
camera.near = 0.05; camera.far = 400; camera.updateProjectionMatrix();

L.camC     = addLabel('Camera<br>center', S.camC, { fontSize:'17px', offset:[-48,-30] });
L.camPlane = addLabel('Camera plane', IMG_Q, { fontSize:'17px', offset:[-6,-16] });
L.surf     = addLabel('planar surface', PL_O, { fontSize:'17px', offset:[62,26] });
L.ax       = addLabel('<i>x</i>', IMG_Q, { fontSize:'17px', offset:[16,10] });
L.ay       = addLabel('<i>y</i>', IMG_Q, { fontSize:'17px', offset:[-16,-2] });
L.wx       = addLabel('<i>X</i>', PL_O, { fontSize:'16px', offset:[16,-4] });
L.wy       = addLabel('<i>Y</i>', PL_O, { fontSize:'16px', offset:[16,-8] });
L.wz       = addLabel('<i>Z</i>', PL_O, { fontSize:'16px', offset:[-16,-6] });
L.pw       = addLabel('(<i>X</i>,<i>Y</i>,0)', PL_O, { fontSize:'16px', color:'#00c8e0', offset:[-14,26] });
L.pi       = addLabel('(<i>x</i>,<i>y</i>)', IMG_Q, { fontSize:'16px', color:'#00c8e0', offset:[42,-10] });

L.fSrc = addLabel('world plane &nbsp;<i>Z</i> = 0', new THREE.Vector3(), { fontSize:'15px' });
L.fImg = addLabel('image plane', new THREE.Vector3(), { fontSize:'15px' });
L.fH   = addLabel('<b>H</b>', new THREE.Vector3(), { fontSize:'18px' });
L.fEq  = addLabel('[<i>x y</i> 1]<sup>T</sup> &#8771; H&#183;[<i>X Y</i> 1]<sup>T</sup>', new THREE.Vector3(), { fontSize:'13px' });
L.fPS  = addLabel('(<i>X</i>,<i>Y</i>)', new THREE.Vector3(), { fontSize:'15px', color:'#00c8e0', offset:[-6,-16] });
L.fPI  = addLabel('(<i>x</i>,<i>y</i>)', new THREE.Vector3(), { fontSize:'15px', color:'#00c8e0', offset:[6,-16] });

const LBL3D = [L.camC, L.camPlane, L.surf, L.ax, L.ay, L.wx, L.wy, L.wz, L.pw, L.pi];
const LBLFL = [L.fSrc, L.fImg, L.fH, L.fEq, L.fPS, L.fPI];
function setLblVis(list, on) { for (const e of list) e.div.style.visibility = on ? 'visible' : 'hidden'; }

updateAll();
document.getElementById('btnReset').style.display = '';

/* ── interactive explanations ──────────────────────────────────────────── */
registerInteractive(camSphere, { title:'Camera center',
  body:'The pinhole. Every ray that forms the image passes through this single point — drag it to see the image of the plane re-warp while the point correspondence stays consistent.',
  tooltip:'Camera center — drag me' });
registerInteractive(surfMesh, { title:'Planar surface (Z = 0)',
  body:'The world frame is chosen with its origin on this plane and Z perpendicular to it, so every scene point is (X, Y, 0). The third column of P multiplies Z and therefore drops out.',
  tooltip:'Planar surface: all points have Z = 0' });
registerInteractive(imgMesh, { title:'Image of the plane',
  body:'The cone of rays from the camera center through the surface corners, cut by the image plane. Straight lines stay straight, but parallels converge — a projective (homographic) warp.',
  tooltip:'Image of the planar surface' });
registerInteractive(ptWorld, { title:'(X, Y, 0)',
  body:'A point on the world plane. Its image satisfies [x y 1]ᵀ ≃ H·[X Y 1]ᵀ with the 3×3 homography H.', tooltip:'(X, Y, 0)' });
registerInteractive(ptImage, { title:'(x, y)',
  body:'The image of (X, Y, 0). H is invertible, so this 2D↔2D mapping goes both ways.', tooltip:'(x, y)' });

/* ── flatten / mode switching with eased camera tween ──────────────────── */
let camTween = null;
function setModeGroups(flat) {
  if (flat) { if (g3d.parent) scene.remove(g3d); if (!gflat.parent) scene.add(gflat); }
  else      { if (gflat.parent) scene.remove(gflat); if (!g3d.parent) scene.add(g3d); }
  setLblVis(LBL3D, !flat); setLblVis(LBLFL, flat);
  gridG.visible = S.showGrid;
  for (const l of fSrcGrid) l.visible = S.showGrid;
  for (const l of fImgGrid) l.visible = S.showGrid;
}
function switchMode(flat) {
  if (flat === S.flat) return;
  S.flat = flat;
  const p0 = camera.position.clone(), t0 = controls.target.clone();
  setModeGroups(flat);
  updateAll();
  setCameraView(flat ? VIEWFLAT : VIEW3D);
  const p1 = camera.position.clone(), t1 = controls.target.clone();
  camera.near = 0.05; camera.far = 400; camera.updateProjectionMatrix();
  camera.position.copy(p0); controls.target.copy(t0); controls.update();
  camTween = { p0, p1, t0, t1, start:performance.now(), dur:800 };
  syncUI();
}

/* ── parameter tween (demo steps) ──────────────────────────────────────── */
let parTween = null;
const ease = t => t < 0.5 ? 2*t*t : 1 - Math.pow(-2*t + 2, 2) / 2;

function myTick() {
  requestAnimationFrame(myTick);
  const now = performance.now();
  if (camTween) {
    const k = Math.min(1, (now - camTween.start) / camTween.dur), e = ease(k);
    camera.position.lerpVectors(camTween.p0, camTween.p1, e);
    controls.target.lerpVectors(camTween.t0, camTween.t1, e);
    controls.update();
    if (k >= 1) camTween = null;
  }
  if (parTween) {
    const k = Math.min(1, (now - parTween.start) / parTween.dur), e = ease(k);
    for (const key in parTween.to) S[key] = parTween.from[key] + (parTween.to[key] - parTween.from[key]) * e;
    updateAll(); syncUI();
    if (k >= 1) parTween = null;
  }
}
myTick();

/* ── camera-center dragging ────────────────────────────────────────────── */
let dragging = false;
const dragRay = new THREE.Raycaster();
const dragPlane = new THREE.Plane();
const ndc = new THREE.Vector2();
function setNdc(e) {
  const r = canvas.getBoundingClientRect();
  ndc.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  ndc.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
canvas.addEventListener('pointerdown', (e) => {
  if (S.flat) return;
  setNdc(e); dragRay.setFromCamera(ndc, camera);
  if (dragRay.intersectObject(camSphere, false).length) {
    dragging = true;
    controls.enabled = false;
    e.stopPropagation();
    const n = new THREE.Vector3(); camera.getWorldDirection(n);
    dragPlane.setFromNormalAndCoplanarPoint(n, S.camC);
    canvas.style.cursor = 'grabbing';
  }
}, true);
canvas.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  setNdc(e); dragRay.setFromCamera(ndc, camera);
  const p = new THREE.Vector3();
  if (dragRay.ray.intersectPlane(dragPlane, p)) {
    p.y = THREE.MathUtils.clamp(p.y, -1.2, 3.6);
    p.z = THREE.MathUtils.clamp(p.z, -2.5, 3.2);
    p.x = THREE.MathUtils.clamp(p.x, -8.0, 0.5);
    const sd = IMG_N.dot(p.clone().sub(IMG_Q));
    if (sd > -1.0) p.addScaledVector(IMG_N, -1.0 - sd);
    S.camC.copy(p);
    updateAll();
  }
}, true);
window.addEventListener('pointerup', () => {
  if (dragging) { dragging = false; controls.enabled = true; canvas.style.cursor = 'default'; }
});

/* ── UI wiring ─────────────────────────────────────────────────────────── */
const el = id => document.getElementById(id);
const sTilt = el('sTilt'), sPX = el('sPX'), sPY = el('sPY');

function syncUI() {
  sTilt.value = S.planeTilt.toFixed(0);
  sPX.value = S.pointX.toFixed(2);
  sPY.value = S.pointY.toFixed(2);
  el('vTilt').textContent = S.planeTilt.toFixed(0);
  el('vPX').textContent = S.pointX.toFixed(2);
  el('vPY').textContent = S.pointY.toFixed(2);
  el('bMode3D').classList.toggle('active', !S.flat);
  el('bModeFlat').classList.toggle('active', S.flat);
  el('bGrid').classList.toggle('active', S.showGrid);
  el('bH').classList.toggle('active', S.showH);
  el('hWrap').style.display = S.showH ? '' : 'none';
}

sTilt.addEventListener('input', () => { parTween = null; S.planeTilt = +sTilt.value; updateAll(); syncUI(); });
sPX.addEventListener('input',  () => { parTween = null; S.pointX = +sPX.value; updateAll(); syncUI(); });
sPY.addEventListener('input',  () => { parTween = null; S.pointY = +sPY.value; updateAll(); syncUI(); });

el('bMode3D').addEventListener('click', () => switchMode(false));
el('bModeFlat').addEventListener('click', () => switchMode(true));
el('bGrid').addEventListener('click', () => {
  S.showGrid = !S.showGrid;
  gridG.visible = S.showGrid;
  for (const l of fSrcGrid) l.visible = S.showGrid;
  for (const l of fImgGrid) l.visible = S.showGrid;
  syncUI();
});
el('bH').addEventListener('click', () => { S.showH = !S.showH; syncUI(); });

/* ── guided demo ───────────────────────────────────────────────────────── */
const STEPS = [
  { title:'1. Single ray, single point',
    text:'A cyan ray leaves the camera center, pierces the image plane at (x, y), and lands on the world plane at (X, Y, 0). The Z axis of the world frame is perpendicular to the surface, so every scene point has Z = 0.',
    flat:false, grid:false, H:true, p:{ planeTilt:25, pointX:0.9, pointY:0.6 } },
  { title:'2. A whole grid maps to a whole image',
    text:'Turn on the grid: each cell on the plane has a corresponding quadrilateral in the image. The same 3×3 matrix H maps every one of them.',
    flat:false, grid:true, H:true, p:{ planeTilt:25, pointX:0.9, pointY:0.6 } },
  { title:'3. Tilt the plane — foreshortening',
    text:'Tilting the world plane away from the camera compresses the far grid rows in the image, but the points still satisfy Z = 0, so the mapping stays a homography — only H\u2019s entries change.',
    flat:false, grid:true, H:true, p:{ planeTilt:60, pointX:0.9, pointY:0.6 } },
  { title:'4. Collapse to 2D ↔ 2D',
    text:'Drop the depth dimension: the 3×4 projection loses its third column and becomes a 3×3 H. The figure flattens into the source plane on the left and the image plane on the right, with the same point correspondence drawn between them.',
    flat:true, grid:true, H:true, p:{ planeTilt:60, pointX:0.9, pointY:0.6 } }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  S.showGrid = st.grid; S.showH = st.H;
  gridG.visible = S.showGrid;
  for (const l of fSrcGrid) l.visible = S.showGrid;
  for (const l of fImgGrid) l.visible = S.showGrid;
  switchMode(st.flat);
  parTween = { from:{ planeTilt:S.planeTilt, pointX:S.pointX, pointY:S.pointY },
               to:{ ...st.p }, start:performance.now(), dur:750 };
  el('stepTitle').textContent = st.title;
  el('stepText').textContent = st.text;
  syncUI();
}
el('bNext').addEventListener('click', () => goToStep(stepIdx + 1));
el('bPrev').addEventListener('click', () => goToStep(stepIdx - 1));

setModeGroups(false);
syncUI();
el('stepTitle').textContent = STEPS[0].title;
el('stepText').textContent = STEPS[0].text;
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

