<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ELEMENT SPEC
   camera center        -> SphereGeometry(0.20)  black, draggable
   camera image plane   -> thick tube polyline (closed) black, 3.2 x 4.0, near-vertical
   image axes x,y       -> cylinder+cone arrows #00E000 (len 1.0 / 1.2) at lower-left corner
   planar surface       -> quad Mesh #C8C8C8 + thick black tube outline + dashed black diagonal
   world axes X,Y,Z     -> cylinder+cone arrows #FF0000 (len 1.2) + black L right-angle mark
   image of surface     -> quad Mesh #C8C8C8 + thick black outline + dashed diagonal
                           (ray/plane intersection, recomputed on every change)
   projection rays (4)  -> Line + LineDashedMaterial black, C -> surface corners
   helper lines (2)     -> Line + LineDashedMaterial #CCCCCC, C -> near image-plane corners
   cyan points (2)      -> SphereGeometry(0.12) #00E5FF
   cyan ray             -> Line + LineDashedMaterial #00E5FF, C -> (X,Y,0)
   grid + its image     -> thin Lines (#444), OFF by default (not in source figure)
   flattened mode       -> two coplanar panels: source square (left), H-warped square (right)
*/

/* ── constants ─────────────────────────────────────────────────────────── */
const IMG_Q  = new THREE.Vector3(-1.2, 0.0, 0.4);
const IMG_R  = new THREE.Vector3(-0.2, 0, -0.98).normalize();
const IMG_UP = new THREE.Vector3(0, 1, 0);
const IMG_N  = new THREE.Vector3().crossVectors(IMG_R, IMG_UP).normalize();
const IMG_HW = 1.6, IMG_HH = 2.0;
const PL_O   = new THREE.Vector3(4.0, -1.6, 0.4);
const PL_HU  = 3.0, PL_HV = 2.0;
const C_GRAY = 0xC8C8C8, C_CYAN = 0x00E5FF, C_GREEN = 0x00E000, C_RED = 0xFF0000;
const NX = 7, NY = 5;
const YUP = new THREE.Vector3(0, 1, 0);

const VIEW3D   = { projection:'perspective', azimuthDeg:35, elevationDeg:22, rollDeg:0, heightFraction:0.80 };
const VIEWFLAT = { projection:'perspective', azimuthDeg:90, elevationDeg:0,  rollDeg:0, heightFraction:0.80 };

const S = {
  camC: new THREE.Vector3(-4.2, 1.6, 1.0),
  planeTilt: 25, pointX: 0.9, pointY: 0.6,
  flat: false, showGrid: false, showH: true
};

/* ── builders ──────────────────────────────────────────────────────────── */
function makeLine(color, o = {}) {
  const dashed = !!o.dashed;
  const mat = dashed
    ? new THREE.LineDashedMaterial({ color, dashSize:o.dash ?? 0.26, gapSize:o.gap ?? 0.20,
        transparent:(o.opacity ?? 1) < 1, opacity:o.opacity ?? 1 })
    : new THREE.LineBasicMaterial({ color, transparent:(o.opacity ?? 1) < 1, opacity:o.opacity ?? 1 });
  const l = new THREE.Line(new THREE.BufferGeometry(), mat);
  l.userData.dashed = dashed;
  return l;
}
function setPts(line, pts) {
  line.geometry.dispose();
  line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  if (line.userData.dashed) line.computeLineDistances();
}

/* thick screen-consistent outlines: cylinders + joint spheres */
function makeThick(color, radius) {
  const g = new THREE.Group();
  g.userData = { mat:new THREE.MeshBasicMaterial({ color }), radius, segs:[], joints:[] };
  return g;
}
function setThick(g, pts) {
  const ud = g.userData, n = pts.length - 1;
  while (ud.segs.length < n) {
    const m = new THREE.Mesh(new THREE.CylinderGeometry(1, 1, 1, 10), ud.mat);
    ud.segs.push(m); g.add(m);
  }
  while (ud.joints.length < pts.length) {
    const s = new THREE.Mesh(new THREE.SphereGeometry(1, 10, 8), ud.mat);
    ud.joints.push(s); g.add(s);
  }
  for (let i = 0; i < ud.segs.length; i++) {
    const m = ud.segs[i];
    if (i >= n) { m.visible = false; continue; }
    const a = pts[i], b = pts[i + 1];
    const dir = new THREE.Vector3().subVectors(b, a);
    const len = dir.length();
    if (len < 1e-6) { m.visible = false; continue; }
    m.visible = true;
    m.position.copy(a).addScaledVector(dir, 0.5);
    m.scale.set(ud.radius, len, ud.radius);
    m.quaternion.setFromUnitVectors(YUP, dir.normalize());
  }
  for (let i = 0; i < ud.joints.length; i++) {
    const s = ud.joints[i];
    if (i >= pts.length) { s.visible = false; continue; }
    s.visible = true;
    s.position.copy(pts[i]);
    s.scale.setScalar(ud.radius);
  }
}
function makeQuad(color, opacity) {
  const m = new THREE.MeshBasicMaterial({ color, side:THREE.DoubleSide, transparent:true,
    opacity, polygonOffset:true, polygonOffsetFactor:2, polygonOffsetUnits:2 });
  return new THREE.Mesh(new THREE.BufferGeometry(), m);
}
function setQuad(mesh, c) {
  const a = new Float32Array([
    c[0].x,c[0].y,c[0].z, c[1].x,c[1].y,c[1].z, c[2].x,c[2].y,c[2].z,
    c[0].x,c[0].y,c[0].z, c[2].x,c[2].y,c[2].z, c[3].x,c[3].y,c[3].z ]);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(a, 3));
  g.computeBoundingSphere();
  mesh.geometry.dispose();
  mesh.geometry = g;
}
function makeArrow(color, shaftR, headR, headL) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, 1, 12), mat);
  const head  = new THREE.Mesh(new THREE.ConeGeometry(headR, headL, 18), mat);
  g.add(shaft, head);
  g.userData.set = (origin, dir, len) => {
    const dn = dir.clone().normalize();
    const sl = Math.max(0.01, len - headL);
    shaft.scale.set(1, sl, 1);
    shaft.position.copy(origin).addScaledVector(dn, sl / 2);
    head.position.copy(origin).addScaledVector(dn, sl + headL / 2);
    const q = new THREE.Quaternion().setFromUnitVectors(YUP, dn);
    shaft.quaternion.copy(q); head.quaternion.copy(q);
  };
  return g;
}

/* ── geometry math ─────────────────────────────────────────────────────── */
function planeBasis(deg) {
  const a = THREE.MathUtils.degToRad(deg);
  return { u:new THREE.Vector3(1,0,0),
           v:new THREE.Vector3(0, Math.sin(a), -Math.cos(a)),
           n:new THREE.Vector3(0, Math.cos(a),  Math.sin(a)) };
}
function worldPt(B, X, Y) {
  return PL_O.clone().addScaledVector(B.u, X).addScaledVector(B.v, Y);
}
function projImg(W) {
  const dir = W.clone().sub(S.camC);
  const den = IMG_N.dot(dir);
  if (Math.abs(den) < 1e-6) return null;
  const t = IMG_N.dot(IMG_Q.clone().sub(S.camC)) / den;
  if (!isFinite(t)) return null;
  return S.camC.clone().addScaledVector(dir, t);
}
function computeH() {
  const B = planeBasis(S.planeTilt);
  const A = PL_O.clone().sub(S.camC);
  const e = S.camC.clone().sub(IMG_Q);
  const D = IMG_Q.clone().sub(S.camC).dot(IMG_N);
  const a0 = IMG_N.dot(A), a1 = IMG_N.dot(B.u), a2 = IMG_N.dot(B.v);
  const er = e.dot(IMG_R), et = e.dot(IMG_UP);
  const Ar = A.dot(IMG_R), At = A.dot(IMG_UP);
  const ur = B.u.dot(IMG_R), ut = B.u.dot(IMG_UP);
  const vr = B.v.dot(IMG_R), vt = B.v.dot(IMG_UP);
  return [
    [er*a1 + D*ur, er*a2 + D*vr, er*a0 + D*Ar],
    [et*a1 + D*ut, et*a2 + D*vt, et*a0 + D*At],
    [a1, a2, a0]
  ];
}
function applyH(H, X, Y) {
  const w = H[2][0]*X + H[2][1]*Y + H[2][2];
  return [ (H[0][0]*X + H[0][1]*Y + H[0][2]) / w,
           (H[1][0]*X + H[1][1]*Y + H[1][2]) / w ];
}

/* ── 3D group ──────────────────────────────────────────────────────────── */
const g3d = new THREE.Group();
scene.add(g3d);

const camSphere = new THREE.Mesh(new THREE.SphereGeometry(0.20, 26, 20),
                                 new THREE.MeshBasicMaterial({ color:0x000000 }));
g3d.add(camSphere);

const imgPlaneOutline = makeThick(0x000000, 0.030);
g3d.add(imgPlaneOutline);

const surfMesh = makeQuad(C_GRAY, 0.96);
const surfOutline = makeThick(0x000000, 0.048);
const surfDiag = makeLine(0x000000, { dashed:true, dash:0.30, gap:0.22 });
g3d.add(surfMesh, surfOutline, surfDiag);

const imgMesh = makeQuad(C_GRAY, 0.96);
const imgOutline = makeThick(0x000000, 0.034);
const imgDiag = makeLine(0x000000, { dashed:true, dash:0.16, gap:0.12 });
