/* ── tweening loop ─────────────────────────────────────────────────────── */
let parTween = null;
const ease = t => t < 0.5 ? 2*t*t : 1 - Math.pow(-2*t + 2, 2) / 2;

function myTick() {
  requestAnimationFrame(myTick);
  const now = performance.now();
  if (camTween) {
    const k = Math.min(1, (now - camTween.start) / camTween.dur), e = ease(k);
    camera.position.lerpVectors(camTween.p0, camTween.p1, e);
    controls.target.lerpVectors(camTween.t0, camTween.t1, e);
    controls.update();
    if (k >= 1) camTween = null;
  }
  if (parTween) {
    const k = Math.min(1, (now - parTween.start) / parTween.dur), e = ease(k);
    for (const key in parTween.to) S[key] = parTween.from[key] + (parTween.to[key] - parTween.from[key]) * e;
    updateAll(); syncUI();
    if (k >= 1) parTween = null;
  }
}
