  if (S.flat) return;
  setNdc(e); dragRay.setFromCamera(ndc, camera);
  if (dragRay.intersectObject(camSphere, false).length) {
    dragging = true;
    controls.enabled = false;
    e.stopPropagation();
    const n = new THREE.Vector3(); camera.getWorldDirection(n);
    dragPlane.setFromNormalAndCoplanarPoint(n, S.camC);
    canvas.style.cursor = 'grabbing';
  }
}, true);
canvas.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  setNdc(e); dragRay.setFromCamera(ndc, camera);
  const p = new THREE.Vector3();
  if (dragRay.ray.intersectPlane(dragPlane, p)) {
    p.y = THREE.MathUtils.clamp(p.y, -1.2, 3.8);
    p.z = THREE.MathUtils.clamp(p.z, -2.6, 3.4);
    p.x = THREE.MathUtils.clamp(p.x, -8.5, 0.5);
    const sd = IMG_N.dot(p.clone().sub(IMG_Q));
