/* ── update ────────────────────────────────────────────────────────────── */
function update3D() {
  const B = planeBasis(S.planeTilt);
  const C = S.camC;
  camSphere.position.copy(C);

  const cs = [ worldPt(B,-PL_HU,-PL_HV), worldPt(B, PL_HU,-PL_HV),
               worldPt(B, PL_HU, PL_HV), worldPt(B,-PL_HU, PL_HV) ];
  setQuad(surfMesh, cs);
  setThick(surfOutline, [...cs, cs[0]]);
  setPts(surfDiag, [cs[0], cs[2]]);

  const ic = cs.map(projImg);
  const ok = ic.every(p => p);
  imgMesh.visible = imgOutline.visible = imgDiag.visible = ok;
  if (ok) {
    setQuad(imgMesh, ic);
    setThick(imgOutline, [...ic, ic[0]]);
    setPts(imgDiag, [ic[0], ic[2]]);
  }
  for (let i = 0; i < 4; i++) setPts(rays[i], [C, cs[i]]);
  setPts(helpers[0], [C, IPC[0]]);
  setPts(helpers[1], [C, IPC[3]]);

  /* green image axes at the lower-left corner of the camera plane */
  const go = IPC[3].clone();
  axY.userData.set(go, IMG_UP, AXL_GY);
  axX.userData.set(go, IMG_R, AXL_G);
  tipData.ax.tip.copy(go).addScaledVector(IMG_R, AXL_G);   tipData.ax.dir.copy(IMG_R);
  tipData.ay.tip.copy(go).addScaledVector(IMG_UP, AXL_GY); tipData.ay.dir.copy(IMG_UP);

  /* red world frame near the left region of the planar surface */
  const wo = worldPt(B, -1.0, -1.4);
  wX.userData.set(wo, B.u, AXL_R);
  wY.userData.set(wo, B.v, AXL_R);
  wZ.userData.set(wo, B.n, AXL_R);
  tipData.wx.tip.copy(wo).addScaledVector(B.u, AXL_R); tipData.wx.dir.copy(B.u);
  tipData.wy.tip.copy(wo).addScaledVector(B.v, AXL_R); tipData.wy.dir.copy(B.v);
  tipData.wz.tip.copy(wo).addScaledVector(B.n, AXL_R); tipData.wz.dir.copy(B.n);

  const m = 0.46;
  setThick(lMark, [ wo.clone().addScaledVector(B.u, m),
                    wo.clone().addScaledVector(B.u, m).addScaledVector(B.n, m),
                    wo.clone().addScaledVector(B.n, m) ]);

  /* cyan correspondence */
  const W = worldPt(B, S.pointX, S.pointY);
  const I = projImg(W);
  ptWorld.position.copy(W);
  if (I) { ptImage.position.copy(I); ptImage.visible = true; } else ptImage.visible = false;
  setPts(cyanRay, [C, W]);

  /* grid */
  let k = 0;
  for (let i = 0; i < NX; i++) {
    const X = -PL_HU + 2 * PL_HU * i / (NX - 1);
    const p0 = worldPt(B, X, -PL_HV), p1 = worldPt(B, X, PL_HV);
    setPts(planeGrid[k], [p0, p1]);
    const q0 = projImg(p0), q1 = projImg(p1);
    if (q0 && q1) setPts(imgGrid[k], [q0, q1]);
    k++;
  }
  for (let j = 0; j < NY; j++) {
    const Y = -PL_HV + 2 * PL_HV * j / (NY - 1);
    const p0 = worldPt(B, -PL_HU, Y), p1 = worldPt(B, PL_HU, Y);
    setPts(planeGrid[k], [p0, p1]);
    const q0 = projImg(p0), q1 = projImg(p1);
    if (q0 && q1) setPts(imgGrid[k], [q0, q1]);
    k++;
  }

  /* label anchors */
  if (L.camC) {
    L.camC.pos.copy(C);
    L.camPlane.pos.copy(IMG_Q).addScaledVector(IMG_UP, IMG_HH).addScaledVector(IMG_R, -0.5);
    L.surf.pos.copy(worldPt(B, PL_HU * 1.05, PL_HV * 0.35));
    L.pw.pos.copy(W);
    if (I) L.pi.pos.copy(I);
  }
}

function updateFlat() {
  const H = computeH();
  const corner = [[-PL_HU,-PL_HV],[PL_HU,-PL_HV],[PL_HU,PL_HV],[-PL_HU,PL_HV]];
  const ims = corner.map(c => applyH(H, c[0], c[1]));
  let mnx = 1e9, mxx = -1e9, mny = 1e9, mxy = -1e9;
  for (const p of ims) { mnx = Math.min(mnx,p[0]); mxx = Math.max(mxx,p[0]); mny = Math.min(mny,p[1]); mxy = Math.max(mxy,p[1]); }
  const cx = (mnx+mxx)/2, cy = (mny+mxy)/2;
  const sc = 1.45 / Math.max((mxx-mnx)/2, (mxy-mny)/2, 1e-3);
  const sp = (X,Y) => new THREE.Vector3(FL_LC.x + X*FL_S, FL_LC.y + Y*FL_S, 0);
  const ip = (X,Y) => { const q = applyH(H,X,Y); return new THREE.Vector3(FL_RC.x + (q[0]-cx)*sc, FL_RC.y + (q[1]-cy)*sc, 0); };

  const sq = corner.map(c => sp(c[0], c[1]));
  const iq = corner.map(c => ip(c[0], c[1]));
  setQuad(fSrcMesh, sq); setThick(fSrcOut, [...sq, sq[0]]);
  setQuad(fImgMesh, iq); setThick(fImgOut, [...iq, iq[0]]);

  let k = 0;
  for (let i = 0; i < NX; i++) {
    const X = -PL_HU + 2*PL_HU*i/(NX-1);
    setPts(fSrcGrid[k], [sp(X,-PL_HV), sp(X,PL_HV)]);
    setPts(fImgGrid[k], [ip(X,-PL_HV), ip(X,PL_HV)]);
    k++;
  }
  for (let j = 0; j < NY; j++) {
    const Y = -PL_HV + 2*PL_HV*j/(NY-1);
    setPts(fSrcGrid[k], [sp(-PL_HU,Y), sp(PL_HU,Y)]);
    setPts(fImgGrid[k], [ip(-PL_HU,Y), ip(PL_HU,Y)]);
    k++;
  }
  const a = sp(S.pointX, S.pointY), b = ip(S.pointX, S.pointY);
  fPtS.position.copy(a); fPtI.position.copy(b);
  setPts(fLink, [a, b]);
  fAxX.userData.set(sp(0,0), new THREE.Vector3(1,0,0), 0.85);
  fAxY.userData.set(sp(0,0), new THREE.Vector3(0,1,0), 0.85);

  if (L.fSrc) {
    L.fSrc.pos.set(FL_LC.x, FL_LC.y - 2.45, 0);
    L.fImg.pos.set(FL_RC.x, FL_RC.y - 2.45, 0);
    L.fH.pos.set(0, FL_LC.y + 0.48, 0);
    L.fEq.pos.set(0, FL_LC.y - 0.55, 0);
    L.fPS.pos.copy(a);
    L.fPI.pos.copy(b);
  }
}

function updateHTable() {
