/* keep on-screen label size constant regardless of perspective distance */
function refreshLabelFonts() {
  for (const e of lblAll) {
    const dist = Math.max(camera.position.distanceTo(e.pos), 1e-3);
    const px = Math.max(6, e.__px * dist / 8);
    if (Math.abs(px - e.__last) > 0.25) { e.div.style.fontSize = px.toFixed(1) + 'px'; e.__last = px; }
  }
}
/* pin X/Y/Z and x/y right at their arrow tips, offset along the arrow's screen direction */
function updateTipLabels() {
  for (const key in tipData) {
    const t = tipData[key];
    if (!t.e) continue;
    t.e.pos.copy(t.tip);
    const a = t.tip.clone().project(camera);
    const b = t.tip.clone().addScaledVector(t.dir, 0.6).project(camera);
    let dx = (b.x - a.x) * canvas.clientWidth * 0.5;
    let dy = -(b.y - a.y) * canvas.clientHeight * 0.5;
    const len2 = Math.hypot(dx, dy) || 1;
    t.e.offset[0] = dx / len2 * t.pad;
    t.e.offset[1] = dy / len2 * t.pad;
  }
}

